use xiom.io;
type QuizQuestion = {
  question: Str;
  answer: Str;
}

fn check_answer(question: &QuizQuestion, user_answer: Str) -> Bool {
  question.answer == user_answer
}

fn run_quiz(questions: &Vec[QuizQuestion]) -> Int {
  var correct = 0;
  let answers: Vec[Str] = Vec[Str].new();
  answers.push("4"); answers.push("Paris"); answers.push("Purple");

  var i = 0;
  while i < questions.len() {
    let q = questions.get(i).unwrap();
    io.println(q.question.to_str());
    if check_answer(q, answers.get(i).unwrap()) { correct += 1; };
    i += 1;
  };
  correct
}

fn main() -> Int {
  var questions: Vec[QuizQuestion] = Vec[QuizQuestion].new();
  questions.push(QuizQuestion{ question: "2+2?", answer: "4" });
  questions.push(QuizQuestion{ question: "Capital of France?", answer: "Paris" });
  questions.push(QuizQuestion{ question: "Red+Blue?", answer: "Purple" });
  let score = run_quiz(&questions);
  io.println(score.to_str());
  return 0;
}
